    );
    extractor.extractData(connection, parameters);
    List<InvoiceEbsDto> ebsInvoices = extractor.getRowSet().ToList(InvoiceEbsDto.class);
    assertThat(ebsInvoices).containsExactly(
        InvoiceEbsDto.builder()
        .invoiceId(actualInvoiceId)
        .build()
    );
  }

